create type public.tournament_status as enum ('DRAFT','REGISTRATION_OPEN','REGISTRATION_CLOSED','DRAW_READY','DRAW_COMPLETED','IN_PROGRESS','PAUSED','COMPLETED','ARCHIVED');
create type public.member_status as enum ('PENDING','CONFIRMED','REJECTED','WITHDRAWN');
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null, efootball_username text not null, country text, selected_team text, bio text, avatar_url text, is_super_admin boolean not null default false, created_at timestamptz not null default now());
create table public.tournaments (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, invitation_code text unique not null, status public.tournament_status not null default 'DRAFT', min_participants int not null default 6 check (min_participants >= 2), max_participants int check(max_participants is null or max_participants >= min_participants), team_mode text not null default 'NONE' check(team_mode in ('NATIONAL','CLUB','MIXED','NONE')), allow_duplicate_teams boolean not null default true, created_by uuid not null references public.profiles(id), rules text, created_at timestamptz not null default now());
create table public.tournament_members (tournament_id uuid references public.tournaments on delete cascade, profile_id uuid references public.profiles on delete cascade, status public.member_status not null default 'PENDING', approved_at timestamptz, primary key(tournament_id,profile_id));
create table public.groups (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments on delete cascade, label text not null, unique(tournament_id,label));
create table public.group_members (group_id uuid references public.groups on delete cascade, profile_id uuid references public.profiles on delete cascade, primary key(group_id,profile_id));
create table public.matches (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments on delete cascade, group_id uuid references public.groups on delete set null, round text not null, home_profile_id uuid references public.profiles, away_profile_id uuid references public.profiles, home_score int check(home_score >= 0), away_score int check(away_score >= 0), penalties_home int, penalties_away int, status text not null default 'SCHEDULED', winner_profile_id uuid references public.profiles, scheduled_at timestamptz, completed_at timestamptz, check(home_profile_id <> away_profile_id));
create table public.result_submissions (id uuid primary key default gen_random_uuid(), match_id uuid not null references public.matches on delete cascade, submitted_by uuid not null references public.profiles, home_score int not null check(home_score >= 0), away_score int not null check(away_score >= 0), status text not null default 'PENDING', created_at timestamptz not null default now());
create table public.announcements (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments on delete cascade, body text not null, created_by uuid references public.profiles, created_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, tournament_id uuid references public.tournaments on delete cascade, actor_id uuid references public.profiles, action text not null, reason text, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index matches_tournament_idx on public.matches(tournament_id,status); create index members_tournament_idx on public.tournament_members(tournament_id,status);
alter table public.profiles enable row level security; alter table public.tournaments enable row level security; alter table public.tournament_members enable row level security; alter table public.groups enable row level security; alter table public.group_members enable row level security; alter table public.matches enable row level security;
create policy "public tournament reads" on public.tournaments for select using (true); create policy "public profile reads" on public.profiles for select using (true); create policy "public match reads" on public.matches for select using (true); create policy "own profile update" on public.profiles for update using (auth.uid()=id) with check(auth.uid()=id);
create or replace function public.is_tournament_admin(tid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from tournaments t join profiles p on p.id=auth.uid() where t.id=tid and (t.created_by=auth.uid() or p.is_super_admin)) $$;
create policy "admin manages tournaments" on public.tournaments for all using (created_by=auth.uid() or public.is_tournament_admin(id)) with check(created_by=auth.uid() or public.is_tournament_admin(id));
create policy "admins manage members" on public.tournament_members for all using (public.is_tournament_admin(tournament_id)) with check (public.is_tournament_admin(tournament_id));
create policy "users request membership" on public.tournament_members for insert with check (profile_id=auth.uid() and exists(select 1 from tournaments where id=tournament_id and status='REGISTRATION_OPEN'));
create policy "public groups" on public.groups for select using(true); create policy "public group members" on public.group_members for select using(true); create policy "public match writes" on public.matches for all using(public.is_tournament_admin(tournament_id)) with check(public.is_tournament_admin(tournament_id));
